<?php

namespace Combodo\iTop\VCSManagement\Hook;

class VCSBackofficeLinkedStylesheetsExtension implements \iBackofficeStyleExtension, \iBackofficeReadyScriptExtension
{
	public function GetReadyScript(): string
	{
		return <<<JS



    const elements = document.getElementsByClassName('vcs-log');
    Array.from(elements).forEach(element => {
        const eTitle = element.getElementsByClassName('vcs-title')[0];
        eTitle.addEventListener('click', function (e) {
            element.classList.toggle('vcs-open');
        });
    });
    
    document.querySelectorAll('[data-role="vcs-pr-row"]').forEach(row => {
        row.addEventListener('click', function (e) {
        const prRow = e.target.closest('[data-role="vcs-pr-row"]');
        if (prRow) {
            const prUrl = prRow.getAttribute('data-url');
            if (prUrl) {
                window.open(prUrl, '_blank');
            }
        }
    })
    });
    
    
        function UpdateVisiblePRRows(checkbox, table) {
        table.querySelectorAll('[data-role="vcs-pr-row"]').forEach(row => {
            if (checkbox.checked) {
                row.getAttribute('data-state') === 'closed' && !row.getAttribute('data-merged') ? row.style.display = 'none' : row.style.display = '';
            } else {
                row.style.display = '';
            }
        });
    }
    
    document.querySelectorAll('.combodo-vcs-integration--pr--table').forEach(table => {
        let checkbox = table.querySelector('input[type="checkbox"]');
        checkbox.addEventListener('change', () => {
            UpdateVisiblePRRows(checkbox, table)
        })
    });
    


JS;

	}

	public function GetStyle(): string
	{
		return <<<CSS
        
    .vcs-log .vcs-title {
    position: relative;
    padding: 3px 5px 3px 40px;
    margin: -3px;
    border-radius: 5px;
    
    min-width: 150px;
    min-height: 35px;
}

.vcs-log .vcs-title:before {
    content: '';
    position: absolute;
    left: 8px;
     top: 10px;
    display: flex;
    align-self: anchor-center;
    width: 20px;
    height: 20px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position-x: center;
    background-position-y: center;
}

.vcs-log .vcs-title .vcs-state:after {
    color: #b83280;
}

/** COLLAPSE */

.vcs-log.vcs-collapse .vcs-title {
    cursor: pointer;
    padding-right: 35px;
}

.vcs-log.vcs-collapse .vcs-title:hover {
    background-color: rgba(255, 255, 255, 0.4);
}

.vcs-log.vcs-collapse .vcs-title::after {
    border-style: solid;
    border-width: 0.2em 0.2em 0 0;
    content: '';
    display: flex;
    height: 0.6em;
    align-self: anchor-center;
    position: absolute;
    right: 10px;
     top: 10px;
    transform: rotate(135deg);
    width: 0.6em;
}

.vcs-log.vcs-collapse .vcs-content {
    display: none;
}

/** OPEN */
.vcs-log .vcs-open {
    position: absolute;
    font-size: 0.83rem;
    bottom: -19px;
    right: 0px;
    color: #6e7a8a;
    border-radius: 3px;
    padding: 0px 3px;
    cursor: pointer;
}

.vcs-log .vcs-open:hover {
    background-color: rgba(110, 122, 138, 0.09);
}

.vcs-log .vcs-open:before {
    content: 'View on GitHub';
}

.vcs-log .vcs-open:after {
    font-family: "Font Awesome 5 Free";
    font-weight: 900;
    content: '\f360';
    margin-left: 5px;
}

