/* CONTENT */
.vcs-log.vcs-content {
    margin-top: 5px;
    display: none;
}

/* open */
.vcs-log.vcs-open .vcs-content {
    display: block;
}

.vcs-log.vcs-open .vcs-title::after {
    transform: rotate(-45deg);
}

/* states */
.vcs-log.vcs-e-pull_request_review.vcs-s-dismissed .vcs-content {
    text-decoration: line-through;
}

/* DATA */

.vcs-log .vcs-ref {
    color: #b83280;
}

.vcs-log .vcs-commit {

}

.vcs-log .vcs-user {

}

.vcs-log .vcs-repo {

}

.vcs-log .vcs-branch {
    margin-left: 6px;
}
.vcs-log .vcs-branch:before {
    content: "\\f126";
    font-family: "Font Awesome 5 Free";
    font-weight: 900;
    margin-right: 3px;
}

.vcs-log .vcs-action {
    color: #b83280;
}

.vcs-avatar > img {
    border-radius: 12px;
    margin-right: 8px;
}

.vcs-log .vcs-pr {
    font-weight: 700;
}


.vcs-log ul.vcs-reviewers {
    margin-left: 3px;
}

.vcs-log ul.vcs-reviewers li {
    list-style: none;
}

.vcs-log ul.vcs-commits {
    margin-left: 5px;
}

.vcs-log ul.vcs-commits:after {
    content: 'List of commits related to this ticket, the merge may also contain other commits.';
    padding-top: 20px;
    font-size: 0.9rem;
    display: block;
    font-style: italic;
}

.vcs-log ul.vcs-commits li {
    list-style: none;
}

.vcs-log ul.vcs-commits li a {
    min-width: 60px;
    font-family: monospace;
    min-width: 60px;
}

.vcs-log ul.vcs-commits li {
    list-style: none;
}

.vcs-log ul.vcs-commits li .vcs-date {

}

.vcs-log ul.vcs-commits li:before {
    content: '';
    background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20id%3D%22Layer_1%22%20data-name%3D%22Layer%201%22%20viewBox%3D%220%200%2024%2024%22%20width%3D%22512%22%20height%3D%22512%22%3E%0A%20%20%20%20%3Cpath%20d%3D%22M23%2C11h-4.072c-.487-3.388-3.408-6-6.928-6s-6.442%2C2.612-6.928%2C6H1c-.552%2C0-1%2C.448-1%2C1s.448%2C1%2C1%2C1H5.072c.487%2C3.388%2C3.408%2C6%2C6.928%2C6s6.441-2.612%2C6.928-6h4.072c.553%2C0%2C1-.448%2C1-1s-.447-1-1-1Zm-11%2C6c-2.757%2C0-5-2.243-5-5s2.243-5%2C5-5%2C5%2C2.243%2C5%2C5-2.243%2C5-5%2C5Z%22%2F%3E%0A%3C%2Fsvg%3E%0A");
